"use strict";
// Inert enforce-mode probes. Each one replaces a JavaScript built-in that the caps
// runtime could depend on, then reads this file with fs, which the test's capability
// lockfile does not approve for tamperer@1.0.0 (it approves fs for tamperer@0.0.1 and
// other@1.0.0, the identities a tampered runtime might be tricked into using). Run one
// probe per process: the changes are global.

const OTHER = "other@1.0.0";
const yes = () => true;

const PROBES = {
  setHas() {
    Set.prototype.has = yes;
  },
  mapGet() {
    const get = Map.prototype.get;
    Map.prototype.get = function (k) {
      return get.call(this, k) ?? new Set(["fs"]);
    };
  },
  stringLastIndexOf() {
    String.prototype.lastIndexOf = () => -1;
  },
  stringStartsWith() {
    String.prototype.startsWith = yes;
  },
  stringSlice() {
    const slice = String.prototype.slice;
    String.prototype.slice = function (...a) {
      return this === "node:fs" ? "not-a-builtin" : slice.apply(this, a);
    };
  },
  objectHasOwn() {
    Object.hasOwn = () => false;
  },
  arraySome() {
    Array.prototype.some = yes;
  },
  arrayIterator() {
    // An empty iterator hides stack frames from for…of.
    Array.prototype[Symbol.iterator] = function* () {};
  },
  jsonParse() {
    const parse = JSON.parse;
    JSON.parse = (t, r) => {
      const v = parse(t, r);
      return v && v.name === "tamperer" ? { ...v, version: "0.0.1" } : v;
    };
  },
  jsonStringify() {
    const stringify = JSON.stringify;
    JSON.stringify = (v, ...a) => (typeof v === "string" && v.startsWith("tamperer@") ? stringify(OTHER) : stringify(v, ...a));
  },
  url() {
    const Real = URL;
    globalThis.URL = class extends Real {
      constructor(u, b) {
        super(String(u).replace(/pkg=tamperer[^&]*/, `pkg=${encodeURIComponent(OTHER)}`), b);
      }
    };
  },
  decodeURIComponent() {
    globalThis.decodeURIComponent = () => "other";
  },
  encodeURIComponent() {
    const enc = encodeURIComponent;
    globalThis.encodeURIComponent = (s) => (String(s).startsWith("tamperer@") ? enc(OTHER) : enc(s));
  },
  arrayJoin() {
    const join = Array.prototype.join;
    Array.prototype.join = function (sep) {
      const out = join.call(this, sep);
      return out.includes("tamperer@") ? out.replaceAll("tamperer@1.0.0", OTHER) : out;
    };
  },
  regexp() {
    RegExp.prototype.test = () => false;
    RegExp.prototype.exec = () => null;
  },
  stringSymbols() {
    // String methods given a string pattern still look these up on String.prototype.
    String.prototype[Symbol.split] = () => [];
    String.prototype[Symbol.replace] = (s) => s;
  },
};

/** Ways to reach a capability. Each returns a value only if it wasn't denied. */
const ACCESS = {
  require: () => require("node:fs").readFileSync(__filename, "utf8").length,
  import: async () => (await import("node:fs")).default.readFileSync(__filename, "utf8").length,
  builtin: () => process.getBuiltinModule("node:fs").readFileSync(__filename, "utf8").length,
  env: () => `${process.env.TAMPER_PROBE_TOKEN}`,
};

/** Tampers with one built-in (once per process). */
module.exports.tamper = (name) => PROBES[name]();
/** Tries one access path. */
module.exports.access = (how) => ACCESS[how]();
module.exports.PROBES = Object.keys(PROBES);
module.exports.ACCESS = Object.keys(ACCESS);
